2:import { simpleGit } from "simple-git";
7:import { getGitBundlePathForRelease, isGitBundleCompatible } from "../../utils/gitReleaseBundles.js";
18:export async function cloneLlamaCppRepo(githubOwner, githubRepo, tag, useBundles = true, progressLogs = "stderr", recursive = enableRecursiveClone) {
19:    const gitBundleForTag = !useBundles ? null : await getGitBundlePathForRelease(githubOwner, githubRepo, tag);
